// Politikregistret: över trehundra områden i 26 domäner som spelaren bygger själv. Varje område har
//   type   'slider' (min/max/step/def/unit) eller 'choice' (options med v = -1…1)
//   def    gällande lag i Sverige vid spelets start (= nollpunkten på kompassen)
//   axes   hur området bidrar till de tolv väljaraxlarna (tecken = riktning när värdet ökar)
//   comp   bidrag till den niodimensionella kompassen (ek, auk, glob, prog, cent, mil, sek, mark, miljo)
//   lag    månader tills reformen får full effekt (myndigheternas kapacitet)
//   cost   extra kostnad (+) eller intäkt (−) i mdkr/år jämfört med gällande lag
//   fx     effekter på simuleringen, skrivs in i ett "fx"-objekt som sweden.js läser
//   konst  grundlag: kräver två riksdagsbeslut med ett val emellan. Kan också sitta på ett enskilt
//          alternativ ({ konst: true }) – då kräver just det alternativet grundlagsändring (se needsKonst).
// Ytterligheter – politik bortom det normala svenska samtalet, med realistiska följder i simuleringen:
//   x      på ett alternativ: ytterlighetsalternativ, AI-partier väljer det aldrig
//   ext    hur extremt: 1 radikalt · 2 extremt · 3 systemfientligt (kan finnas utan x på radikala men normala alternativ)
//   demo   hur odemokratiskt: 0 · -1 inskränker rättigheter · -2 monterar ned demokratin · -3 totalitärt/avskaffar val
//   v      normala alternativ ligger på -1…1, ytterligheter upp till ±1,5 så att de drar partiets axlar längre ut
//   reglage med ytterlighetsintervall: extreme(v) → { ext, demo } för ett värde (0/0 i normalintervallet),
//          xFrom = gräns ovanför vilken värdena är extrema, xTo = gräns nedanför vilken värdena är extrema.
//          Normalintervallet är [xTo ?? min, xFrom ?? max] (normalRange); norm() ger -1…1 där och upp till ±1,5 i det extrema.
// Värdena är spelets modell av Sverige – rimliga storleksordningar, inte officiell statistik.
const S = (id, domain, name, o) => ({ id, domain, name, type: 'slider', ...o });
const C = (id, domain, name, o) => ({ id, domain, name, type: 'choice', ...o });
const n = (p, v) => {
  if (p.type === 'choice') return p.options.find((x) => x.id === v)?.v ?? 0;
  const a = p.xTo ?? p.min, b = p.xFrom ?? p.max;
  if (p.xFrom != null && v > b) return 1 + .5 * Math.min(1, (v - b) / (p.max - b));
  if (p.xTo != null && v < a) return -1 - .5 * Math.min(1, (a - v) / (a - p.min));
  return v <= p.def ? (p.def - a ? -(p.def - v) / (p.def - a) : 0) : (b - p.def ? (v - p.def) / (b - p.def) : 0);
}; // -1…1 i normalintervallet, ±1,5 längst ut i ett ytterlighetsintervall
// Hjälpare för kompakta poster: O = ett alternativ, per = effekter per valt alternativ, lin = effekt per enhet
// från gällande lag (noll vid def), kost = mdkr/år per alternativ. Multiplikatorer (asylMult …) multipliceras.
const MULT = new Set(['asylMult', 'arbetskraftMult']);
const addFx = (o, d) => { for (const k in d) o[k] = MULT.has(k) ? (o[k] || 1) * d[k] : (o[k] || 0) + d[k]; };
const O = (id, name, v, desc) => (desc ? { id, name, v, desc } : { id, name, v });
const per = (map) => (v, o) => { if (map[v]) addFx(o, map[v]); };
const lin = (def, map) => (v, o) => { const d = v - def; if (d) for (const k in map) o[k] = (o[k] || 0) + d * map[k]; };
const kost = (map) => (v) => map[v] || 0;
// Ytterlighetsalternativ: X(id, namn, v, ext, demo, beskrivning, { konst: true } …)
const X = (id, name, v, ext, demo, desc, more) => ({ id, name, v, desc, x: true, ext, demo, ...more });
// Gemensamma följder av att bryta mot demokratins grunder: isolering, kapitalflykt, utvandring och motstånd
const auktoritart = (k) => ({ euRel: -45 * k, usaRel: -25 * k, investeringar: -1.2 * k, fdi: -40 * k, utvandring: 8 * k, protester: 15 * k, polarisering: 6 * k, extremism: 4 * k, oro: 5 * k });
// Återvandring: antalet (reglaget) och formen (valet) verkar tillsammans. Båda skriver in sitt värde och den
// som körs sist räknar fram effekten. Frivilliga former mättas – bara en del av målet vill faktiskt åka.
// Nyckeln aterv (tusen/år utöver dagens nivå) begränsas i sweden.js av hur många som finns kvar att flytta.
const ATERV_DEF = 8000;
function atervandringFx(o) {
  if (o._atervAntal == null || o._atervForm == null || o._atervKlar) return;
  o._atervKlar = true;
  const A = o._atervAntal / 1000, base = ATERV_DEF / 1000, extra = Math.max(0, A - base), form = o._atervForm;
  const tak = { frivillig: 25, villkorad: 60 }[form];
  const eff = tak ? tak * (1 - Math.exp(-extra / tak)) : extra; // tusen/år som faktiskt lämnar utöver i dag
  addFx(o, { aterv: eff + Math.min(0, A - base) });
  if (tak) o.utg = (o.utg || 0) - (extra - eff) * .35; // bidragen till dem som aldrig åkte betalas inte ut
  const tv = form === 'tvingande_utlandska' || form === 'tvingande_alla', k = form === 'tvingande_alla' ? 1.4 : 1;
  // arbetskraft lämnar: vården, omsorgen och företagen tappar folk
  addFx(o, { growth: -eff * (tv ? .011 : .006), vardkvalitet: -eff * .03, aldre: -eff * .04, sjukskoterskor: -eff * .003, konkurser: eff * (tv ? .015 : .005), polarisering: eff * .04 });
  if (form === 'villkorad') addFx(o, { fattigdom: 1, barnfattigdom: 1, integration: -1.5, euRel: -5, protester: 3, kommunekonomi: -1 });
  if (tv) {
    addFx(o, { rattssakerhet: -Math.min(45, 8 + eff * .12) * k, euRel: -Math.min(70, 15 + eff * .25) * k, fnRel: -Math.min(70, 15 + eff * .25) * k, usaRel: -Math.min(35, eff * .1) * k,
      protester: Math.min(45, 8 + eff * .15) * k, polarisering: Math.min(20, 4 + eff * .05) * k, sammanhallning: -Math.min(30, 4 + eff * .1) * k, integration: -Math.min(25, 3 + eff * .08) * k,
      extremism: Math.min(20, 3 + eff * .06) * k, oro: Math.min(20, 2 + eff * .06) * k, demokrati: -Math.min(3, .5 + eff * .008) * k, utvandring: eff * .12 * k, export: -Math.min(.2, eff * .0006) * k,
      investeringar: -Math.min(5, eff * .015) * k, fdi: -Math.min(120, eff * .4) * k, fortroendePolis: -Math.min(20, eff * .06) * k, gang: eff * .015, handlaggning: Math.min(6, eff * .02), arbetsloshet: Math.min(2, eff * .005) });
    if (form === 'tvingande_alla') addFx(o, { demokrati: -1, rattssakerhet: -15, euRel: -20, atervMedb: 1 });
  }
}

