export const POLICY_BY_ID = Object.fromEntries(POLICIES.map((p) => [p.id, p]));
export const norm = n;
export const defaultPolicy = () => Object.fromEntries(POLICIES.map((p) => [p.id, p.def]));
export const policyLabel = (p, v) => (p.type === 'choice' ? (p.options.find((o) => o.id === v)?.name ?? '?') : `${typeof v === 'number' ? (Number.isInteger(p.step) ? v : v.toFixed(p.step < .1 ? 2 : 1)).toString().replace('.', ',') : v}${p.unit ? ' ' + p.unit : ''}`);
export const BUDGET_POLICY = Object.fromEntries(POLICIES.filter((p) => p.budget).map((p) => [p.budget, p.id]));
// Ytterligheter: normalintervallet för ett reglage, markörerna för ett värde och om värdet kräver grundlagsändring
export const normalRange = (p) => [p.xTo ?? p.min, p.xFrom ?? p.max];
export function extremeOf(p, v) {
  if (p.type === 'choice') { const o = p.options.find((x) => x.id === v); return { x: !!o?.x, ext: o?.ext || 0, demo: o?.demo || 0 }; }
  const m = p.extreme ? p.extreme(v) : null;
  return { x: (p.xFrom != null && v > p.xFrom) || (p.xTo != null && v < p.xTo), ext: m?.ext || 0, demo: m?.demo || 0 };
}
export const needsKonst = (p, to) => !!(p.konst || (p.type === 'choice' && p.options.find((o) => o.id === to)?.konst));
